() => {
  const searchBox = document.querySelector('textarea[name="q"], input[name="q"]');
  if (searchBox) {
    searchBox.value = '秒懂金融';
    searchBox.dispatchEvent(new Event('input', { bubbles: true }));
    return 'Success: Set search value to 秒懂金融';
  }
  return 'Error: Search box not found';
}

() => {
  // 尝试关闭登录弹窗
  const closeBtn = document.querySelector('.login-modal-close, [class*="close"], [class*="modal"] button, .modal button');
  if (closeBtn) {
    closeBtn.click();
    return 'Closed login modal';
  }

  // 或者点击遮罩层外面
  const mask = document.querySelector('[class*="mask"], [class*="overlay"]');
  if (mask && mask.parentElement) {
    mask.parentElement.click();
    return 'Clicked mask';
  }

  // 直接设置弹窗为不可见
  const modal = document.querySelector('[class*="modal"]');
  if (modal) {
    modal.style.display = 'none';
    return 'Hidden modal';
  }

  return 'Could not close modal';
}

() => {
  // 检查所有 localStorage
  const localStorageData = {};
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    localStorageData[key] = localStorage.getItem(key);
  }

  // 检查所有 sessionStorage
  const sessionStorageData = {};
  for (let i = 0; i < sessionStorage.length; i++) {
    const key = sessionStorage.key(i);
    sessionStorageData[key] = sessionStorage.getItem(key);
  }

  // 获取所有全局变量中可能包含 supabase 配置的
  const supabaseConfig = typeof window.supabase !== 'undefined' ? 'supabase global exists' : 'no supabase global';

  return {
    localStorage: localStorageData,
    sessionStorage: sessionStorageData,
    supabaseGlobal: supabaseConfig,
    pageURL: window.location.href,
    userAgent: navigator.userAgent
  };
}

() => {
  // 尝试获取 supabase 客户端配置
  const scripts = Array.from(document.querySelectorAll('script'));
  const configScript = scripts.find(s => s.textContent.includes('supabase'));

  // 检查是否有内联配置
  const inlineConfig = {
    supabaseUrl: typeof SUPABASE_URL !== 'undefined' ? SUPABASE_URL : 'not found',
    supabaseKey: typeof SUPABASE_ANON_KEY !== 'undefined' ? 'found' : 'not found'
  };

  // 查找所有包含 supabase 的脚本标签
  const supabaseScripts = scripts
    .filter(s => s.textContent.toLowerCase().includes('supabase'))
    .map(s => ({
      src: s.src,
      hasContent: s.textContent.length > 0,
      preview: s.textContent.substring(0, 200)
    }));

  return {
    inlineConfig,
    supabaseScripts,
    totalScripts: scripts.length
  };
}

